def _case_run(_tested_function, effective_curvature_parameter, mode_spectrum):
    import numpy as np

    def _pack_minimum(result, spectrum, tan_alpha=4.4, speed=1.0):
        r = np.asarray(result, dtype=float)
        if r.shape != (spectrum.shape[1] + 1,) or not np.all(np.isfinite(r)) or r[0] <= 0.0:
            return np.zeros(4, dtype=float)
        phases = r[1:]
        in_range = float(np.all((phases >= 0.0) & (phases < 2.0 * np.pi)))
        again = effective_curvature_parameter(phases.copy(), spectrum.copy(), tan_alpha, speed)
        consistent = float(abs(again - r[0]) <= 1e-09 * abs(again))
        cos_alpha = 1.0 / np.sqrt(1.0 + tan_alpha * tan_alpha)
        sin_alpha = tan_alpha * cos_alpha
        scale = 0.5 * cos_alpha ** 3 / (speed * sin_alpha * np.sum(spectrum[0] * spectrum[1]))
        return np.array([r[0] / scale - 1.0, 1.0, in_range, consistent])
    s = mode_spectrum(num_modes=3, bw2=0.19, omega1=0.11, tan_alpha=4.4)
    return _pack_minimum(_tested_function(s.copy(), num_starts=300, num_iterations=800), s)
assert np.allclose(_case_run(phase_space_minimum, effective_curvature_parameter, mode_spectrum), target)

